style.css:
img {
  max-width: 100%;   /* Ensures image is responsive /
  height: auto;      / Maintains aspect ratio /
  display: block;    / Removes space below the image /
  object-fit: cover; / Optional: makes image fill its container /
}

/ Optional: If you want to control the container /
.image-container {
  width: 100%;       / Ensures the container spans the full width /
  height: 400px;     / Sets a fixed height for the container (adjustable) /
  overflow: hidden;  / Hides any overflow if object-fit is used */
}
